def execution_summary(results):
    total = len(results)
    passed = results.count("pass")
    executed = passed + results.count("fail")
    return {
        "total": total,
        "executed": executed,
        "execution_pct": round(executed / total * 100, 1) if total else 0.0,
        "pass_pct": round(passed / executed * 100, 1) if executed else 0.0,
    }
